// #30dabb (9f3336dd127bdb2d7530dabb) — /simulations на 1280…1920 (возврат 04.11, реджект «1280–1313 таблица прокручивается»):
//  AC3 «אין גלילה אופקית ואין שבירת טבלאות ברוחבים 1280–1920»: нет прокрутки страницы и таблицы, «המשך עריכה» целиком;
//  AC1/AC2: контент 40px от левого края окна и 40px от бокового меню (1440 = Figma 761:1998: контент 40…1144, меню 240);
//  1920 — контент растягивается на свободное место, пустой полосы слева нет.
// Роль business (testim). Только чтение → @prod-safe. Экран бизнеса — только десктоп.
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';

const TAG = '#30dabb · #9f3336dd127bdb2d7530dabb';
const WIDTHS = [1280, 1366, 1440, 1920];

/** Страница, панель таблицы (ближайший предок с фоном/рамкой/скруглением), боковое меню, обёртки с прокруткой. */
async function measure(page: Page) {
  return page.evaluate(() => {
    const isPanel = (el: Element) => {
      const cs = getComputedStyle(el);
      const bg = cs.backgroundColor !== 'rgba(0, 0, 0, 0)' && cs.backgroundColor !== 'transparent';
      return bg || parseFloat(cs.borderTopWidth) > 0 || parseFloat(cs.borderTopLeftRadius) > 0 || cs.backdropFilter !== 'none';
    };
    const table = document.querySelector('main table') as HTMLElement | null;
    const scrollers: string[] = [];
    let panel: Element | null = null;
    for (let el: Element | null = table; el && el.tagName !== 'MAIN'; el = el.parentElement) {
      const h = el as HTMLElement;
      if (h.scrollWidth > h.clientWidth + 1) scrollers.push(`${el.tagName} ${h.scrollWidth}>${h.clientWidth}`);
      if (el !== table && !panel && isPanel(el)) panel = el;
    }
    // Боковое меню: панель-предок ссылки «סימולציות» вне main.
    const navLink = [...document.querySelectorAll('a')].find((a) => !a.closest('main') && a.textContent?.trim() === 'סימולציות');
    let side: Element | null = null;
    for (let el: Element | null = navLink ?? null; el && el !== document.body; el = el.parentElement) {
      const w = el.getBoundingClientRect().width;
      if (isPanel(el) && w >= 200 && w <= 320) side = el;
    }
    const rect = (el: Element | null) => (el ? (({ left, right }) => ({ left: Math.round(left), right: Math.round(right) }))(el.getBoundingClientRect()) : null);
    const h1 = document.querySelector('main h1');
    return {
      vw: window.innerWidth,
      docScroll: document.documentElement.scrollWidth - document.documentElement.clientWidth,
      table: rect(table),
      panel: rect(panel),
      h1: rect(h1),
      side: rect(side),
      scrollers,
    };
  });
}

test.describe(`Список симуляций — ширины 1280–1920 (${TAG})`, () => {
  for (const width of WIDTHS) {
    test(`/simulations @${width}: нет горизонтальной прокрутки, таблица в панели, «המשך עריכה» целиком, контент в 40px от края и от меню @desktop @prod-safe ${TAG}`, async ({ asUser }) => {
      const page = await asUser('business');
      await page.setViewportSize({ width, height: 900 });
      await page.goto('/simulations');
      await expect(page.getByRole('heading', { level: 1, name: 'סימולציות' })).toBeVisible();
      await expect(page.locator('main table tbody tr').first(), 'в списке нет симуляций — нужны данные testim').toBeVisible();

      const m = await measure(page);
      // Источник: AC3 «אין גלילה אופקית ואין שבירת טבלאות ברוחבים 1280–1920»; реджект 21.10 (34/14 px на 1280/1300).
      expect(m.docScroll, 'горизонтальная прокрутка страницы').toBeLessThanOrEqual(0);
      expect(m.scrollers, 'таблица/обёртки прокручиваются по горизонтали').toEqual([]);
      expect(m.panel, 'панель таблицы не найдена').not.toBeNull();
      expect(m.table!.left).toBeGreaterThanOrEqual(m.panel!.left - 1);
      expect(m.table!.right).toBeLessThanOrEqual(m.panel!.right + 1);

      // Источник: AC1/AC2 — 40px слева, 40px от меню (Figma 761:1998; замер программиста 1280: контент 40–984).
      expect(m.side, 'боковое меню не найдено').not.toBeNull();
      expect(Math.abs(m.panel!.left - 40), `левый край контента ${m.panel!.left}, ожидалось 40`).toBeLessThanOrEqual(1);
      expect(Math.abs(m.side!.left - m.panel!.right - 40), `зазор до меню ${m.side!.left - m.panel!.right}, ожидалось 40`).toBeLessThanOrEqual(1);
      if (width === 1440) {
        // Figma 761:1998: контент 40…1144, меню 240.
        expect(Math.abs(m.panel!.right - 1144)).toBeLessThanOrEqual(1);
        expect(Math.abs(m.side!.right - m.side!.left - 240)).toBeLessThanOrEqual(1);
      }
      if (width === 1920) expect(m.panel!.right - m.panel!.left, 'на 1920 контент не растянулся').toBeGreaterThan(1104);

      // Реджект 21.10: «המשך עריכה» обрезалась на 25 px — теперь целиком в панели и в окне.
      const cont = page.locator('main table').getByText('המשך עריכה', { exact: true });
      const n = await cont.count();
      expect(n, 'нет черновика с «המשך עריכה» в списке testim (QA-ED-0411 и др.)').toBeGreaterThan(0);
      for (let i = 0; i < n; i++) {
        const b = (await cont.nth(i).boundingBox())!;
        expect(b.x, `«המשך עריכה» #${i + 1} обрезана слева`).toBeGreaterThanOrEqual(m.panel!.left - 1);
        expect(b.x + b.width, `«המשך עריכה» #${i + 1} обрезана справа`).toBeLessThanOrEqual(m.panel!.right + 1);
        const clipped = await cont.nth(i).evaluate((el: HTMLElement) => el.scrollWidth > el.clientWidth + 1);
        expect(clipped, `«המשך עריכה» #${i + 1}: текст не помещается`).toBe(false);
      }
    });
  }
});
